{
  const t = (70 * Math.PI) / 180, rh = [[0, 0], [4, 0], [4 + 4 * Math.cos(t), 4 * Math.sin(t)], [4 * Math.cos(t), 4 * Math.sin(t)]];
  const an = (i) => { const p = rh[i], u = rh[(i + 3) % 4], v = rh[(i + 1) % 4]; const a = [u[0] - p[0], u[1] - p[1]], b = [v[0] - p[0], v[1] - p[1]]; return (Math.acos((a[0] * b[0] + a[1] * b[1]) / (Math.hypot(...a) * Math.hypot(...b))) * 180) / Math.PI; };
  must(near(an(0), 70) && near(an(2), 70) && near(an(1), 110) && !near(an(0) + an(2), 180), 'rhombus 70 and 110 is not cyclic');
}
const wc6 = A([r`180^\circ - 90^\circ - 60^\circ = 30^\circ`, r`180^\circ - 60^\circ = 120^\circ`, r`30^\circ + 35^\circ = 65^\circ`], 'cyc WE6');
const wc7 = A([r`180^\circ - 70^\circ - 75^\circ = 35^\circ`], 'cyc WE7');
const gRect = cfg({ A: 30, B: 150, C: 210, D: 330 });
must(gRect.ang('A', 'B', 'D') === 90 && gRect.ang('B', 'A', 'C') === 90 && near(gRect.len('A', 'C'), 2) && near(gRect.len('B', 'D'), 2), 'inscribed rectangle: right angles, diagonals are diameters');

